interfaces.interface:

interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  trustLevel?: 'verified' | 'ai_generated' | 'pending';
  confidenceScore?: number;
  sourceType?: 'verified_kb' | 'rag' | 'hitl';
  citations?: Citation[];
  createdAt: Date;
}

task.code-example:
async def generate_response(bot_id: UUID, query: str) -> dict: # Check Verified KB first verified_answer = await verified_kb_service.find_match(bot_id, query) if verified_answer: return { "response": verified_answer.content, "trustLevel": "verified", "confidenceScore": 95, "sourceType": "verified_kb", "responseId": str(uuid4()), "citations": verified_answer.citations }
# RAG pipeline retrieved_chunks = await vector_search(query) answer = await llm_service.generate(query, retrieved_chunks)
# Calculate confidence confidence = await confidence_scoring_service.calculate_score( query, retrieved_chunks, answer )
# Routing decision if confidence >= bot.confidence_threshold: # Auto-send return { "response": answer, "trustLevel": "ai_generated", "confidenceScore": confidence, "sourceType": "rag", "responseId": str(uuid4()), "citations": extract_citations(retrieved_chunks) } else: # HITL queue await hitl_queue.add(query, answer, confidence) return { "response": "I'm checking with the team. You'll receive a verified response shortly.", "trustLevel": "pending", "confidenceScore": confidence, "sourceType": "hitl", "responseId": str(uuid4()) }

typescript-interfaces.interface:

interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  trustLevel?: 'verified' | 'ai_generated' | 'pending';
  confidenceScore?: number;
  sourceType?: 'verified_kb' | 'rag' | 'hitl';
  citations?: Citation[];
  createdAt: Date;
  updatedAt?: Date;
}


interface TrustBadgeProps {
  type: 'verified' | 'ai_generated' | 'pending';
  confidenceScore?: number;
  updatedAt?: Date;
  className?: string;
}


interface PendingVerificationProps {
  messageId: string;
  estimatedWaitTime?: number; // minutes
  onResolved: (response: ChatMessage) => void;
}


interface StatusCheckResponse {
  status: 'pending' | 'resolved';
  response?: {
    id: string;
    content: string;
    trustLevel: 'verified';
    confidenceScore: number;
    sourceType: 'hitl';
    citations: Citation[];
  };
}

